		internal const string QS_WORKSHOP_APPOINTMENT = "SELECT\tw.workshopid,w.apptypeid,w.workshopTitle,w.workshopDescription,w.MaxAttendees,w.WorkshopFee,\r\n\t\tw.partners,w.note,w.location,w.availableForOnlineBooking,w.waitingListMaxUsers,\r\n\t\tat.[description] as apptypedescription,at.appointmentTypeGroupID,at.defaultColour,at.isWorkshop,at.isCourse,\r\n\t\tatg.AppointmentTypeGroupID,atg.title as apptypegrouptitle,\r\n\t\tw.personID AS p1personid,p.firstName AS p1firstname,p.lastName AS p1lastname,p.student_no AS p1student_no,\r\n\t\tw.personID2 AS p2personid,p2.firstName AS p2firstname,p2.lastName AS p2lastname,p2.student_no AS p2student_no,\r\n\t\tw.personID3 AS p3personid,p3.firstName AS p3firstname,p3.lastName AS p3lastname,p3.student_no AS p3student_no,\r\n        aw.maxattendees AS maxattendeescount\r\nFROM\tappointmentworkshops aw LEFT JOIN Workshops w ON w.workshopid=aw.workshopid\r\n        LEFT JOIN AppointmentTypes at ON at.AppTypeID=w.AppTypeID \r\n        LEFT JOIN AppointmentTypeGroups atg ON at.appointmentTypeGroupID=atg.AppointmentTypeGroupID\r\n\t\tLEFT JOIN people p ON p.PersonID=w.personID\r\n\t\tLEFT JOIN people p2 ON p2.PersonID=w.personID2\r\n\t\tLEFT JOIN people p3 ON p3.PersonID=w.personID3\r\nWHERE   aw.appointmentid=@appid\r\nORDER BY at.[description],w.AppTypeID,w.workshopTitle";

