		internal const string QS_WORKSHOP_APPOINTMENTS_BY_APP_TYPE_AND_DATE = "SELECT    a.appointmentid,a.startdate,a.enddate,a.subject AS subtitle,a.location,a.ishidden,a.islocked,a.cancelled,\r\n            am.memotext,am.isencrypted,a.description,a.appcode,sta.showtimeastitle,sta.extraiconid,\r\n            a.personid,p2.firstname,p2.middlename,p2.lastname,p2.student_no,\r\n            a.whoadded AS whobookedpersonid,p.firstname AS whobookedfirstname,p.lastname AS whobookedlastname,p.student_no AS whobookedstudent_no,\r\n            a.dateAdded,a.groupcode,a.extraattendeescount,\r\n            w.workshopid,w.apptypeid,w.workshopTitle,w.workshopDescription,w.MaxAttendees AS DefaultMaxAttendees,w.WorkshopFee,\r\n\t\t    w.partners,w.note,w.location,w.availableForOnlineBooking,w.waitingListMaxUsers,\r\n            CAST(NULL AS int) AS p1personid, -- not loading facilitators for this view\r\n\t\t    CAST(NULL AS int) AS p2personid,\r\n\t\t    CAST(NULL AS int) AS p3personid,\r\n            COALESCE(aw.maxattendees,w.maxattendees) AS maxattendees\r\nFROM        apps a LEFT JOIN people p ON p.personid=a.whoadded\r\n            LEFT JOIN appointmentmemos am ON am.appointmentid=a.appointmentid\r\n            LEFT JOIN people p2 ON p2.personid=a.personid\r\n            LEFT JOIN appointmentworkshops aw ON aw.appointmentid=a.appointmentid\r\n            LEFT JOIN workshops w ON w.workshopid=aw.workshopid\r\n            LEFT JOIN appointmentshowtimeas sta ON sta.appointmentshowtimeasid=a.appcode\r\nWHERE       w.isactive=1 AND a.apptypeid=@apptypeid\r\n            AND NOT ( a.enddate <= @startdate OR a.startdate > @enddate)\r\nORDER BY    a.startdate,a.apptypeid,aw.workshopid";

